const confirmedDates={'South Downs Way 50':['10 April 2027','April'],'Maverick Peak District X-Trail':['5 June 2027','June'],'Race to the Stones':['10–11 July 2027','July'],'Richmond Park Half Marathon':['15 August 2027','August'],'Great North Run':['12 September 2027','September'],'Alloa Half Marathon':['21 March 2027','March'],'Loch Ness Marathon':['26 September 2027','September'],'Inverness Half Marathon':['14 March 2027','March'],'TCS London Marathon':['24–25 April 2027','April'],'Omagh Half Marathon & 5K':['4 April 2027','April'],'Devil o the Highlands Footrace':['24 April 2027','April']};races.forEach(r=>{const d=confirmedDates[r.name];r.date=d?d[0]:(r.date||'2027 date not confirmed');r.dateMonth=d?d[1]:(r.dateMonth||'unknown')});
const baseListWithDates=list;list=function(){const rows=baseListWithDates();const m=document.querySelector('#date-filter')?.value||'any';return m==='any'?rows:rows.filter(r=>r.dateMonth===m)};
